<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(403);exit;}
require_once __DIR__.'/config_loader.php';require_once __DIR__.'/platform.php';
try{$pdo=gszConnectDatabase(gszLoadConfig());if((int)$pdo->query("SELECT COUNT(*) FROM app_migrations WHERE version='250_documents'")->fetchColumn()!==1)throw new RuntimeException('Schema');if((int)$pdo->query('SELECT COUNT(*) FROM admins')->fetchColumn()>0)throw new RuntimeException('Existing admin');$email=getenv('GSZ_SETUP_EMAIL')?:'';if(!filter_var($email,FILTER_VALIDATE_EMAIL)||mb_strlen($email)>190||stream_isatty(STDIN))throw new RuntimeException('Input');$password=rtrim((string)fgets(STDIN,1025),"\r\n");if(strlen($password)<14||strlen($password)>200)throw new RuntimeException('Password policy');$pdo->beginTransaction();$pdo->query('SELECT id FROM app_mutex WHERE id=1 FOR UPDATE')->fetch();if((int)$pdo->query('SELECT COUNT(*) FROM admins')->fetchColumn())throw new RuntimeException('Existing admin');$pdo->prepare('INSERT INTO admins(email,password_hash) VALUES(?,?)')->execute([$email,password_hash($password,PASSWORD_DEFAULT)]);$id=(int)$pdo->lastInsertId();$password='';gszAudit($pdo,$id,'initial_admin_created',['admin_id'=>$id]);$pdo->commit();echo "Erster Administrator angelegt. Kein bestehender Zugang geändert.\n";
}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();fwrite(STDERR,"Admin-Einrichtung gestoppt: vollständiges Schema, leere Admin-Tabelle, GSZ_SETUP_EMAIL und geschützte Standardeingabe mit 14–200 Zeichen erforderlich. Keine Passwörter als Argumente oder im Chat übergeben.\n");exit(1);}
